/**
 * The HPC-035 first/last-name capture modal, built on the generic ZimmModal atom. Rendered
 * through a portal (via ZimmModal) so the overlay escapes the caller's stacking context.
 *
 * @param props see ZimmSubscribeModalProps
 */
export const ZimmSubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: ZimmSubscribeModalProps) => {
  const { mounted, trapRef, firstFocusRef } = useZimmModal({ isOpen, onClose });
  const chrome = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});
  const styles = useMultiStyleConfig(ZIMM_SUBSCRIBE_MODAL_RECIPE, {});

  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    // namedItem returns Element | RadioNodeList | null. The cast keeps `| null` rather than
    // asserting it away — these fields are always single <input>s rendered by ZimmTextInput,
    // but a missing field must stay a null the `?.` below can actually catch. Same pattern as
    // zimmInputAction's handleSubmit.
    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement | null)?.value ?? '';
    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement | null)?.value ?? '';
    onSubmit(firstName.trim(), lastName.trim());
  };
