  name: 'Part of a bundle — price and promo both gated',
  // Default's args with the one flag flipped, so the only thing this story can be proving is the
  // gate. Per the partial's own comment at the price gate, the base header gated its price and
  // its promo together behind `!isProductPartOfBundle`; the extraction kept both, and until this
  // story neither branch was ever entered — every other story here passes `false` or omits it.
  args: {
    name: PRODUCT.name,
    product: PRODUCT,
    priceData: { currentPrice: 795 },
    currency: 'AUD',
    category: [
      { id: 'womens', name: 'Womens' },
      { id: 'womens-clothing-dresses', name: 'Dresses' },
    ],
    isProductPartOfBundle: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // The two gated branches, asserted separately: they are independent conditionals on the same
    // flag — the price is gated inside `ZimmProductContent`'s props, the promo by a wrapping
    // `&&` — so either could be dropped without the other noticing.
    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
    await expect(canvas.queryByTestId('promo-callout')).not.toBeInTheDocument();

    // And the rest of the group is untouched, which is what separates this from `Loading`:
    // `product` and `priceData` are both present here, so an over-broad gate would show up as
    // the name or the description going missing too rather than as a passing test.
    await expect(canvas.getByTestId('product-content')).toBeInTheDocument();
    await expect(canvas.getByRole('heading', { level: 2, name: PRODUCT.name })).toBeInTheDocument();
    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
  },
};

"""
assert s.count(anchor) == 1
s = s.replace(anchor, story + anchor)
io.open(p, 'w', encoding='utf-8').write(s)
print('ok')
